?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Live Display</title><style>html,body{margin:0;width:100%;height:100%;background:#000;overflow:hidden}iframe{display:block;width:100vw;height:100vh;border:0;background:#000}.fx{pointer-events:none;position:fixed;inset:0;z-index:10;display:none;overflow:hidden}.fx.on{display:block}.fx canvas{position:absolute;inset:0;width:100%;height:100%}.cinema-vignette{position:absolute;inset:0;background:radial-gradient(ellipse at center,transparent 35%,rgba(0,0,0,.72) 100%);opacity:0;transition:opacity .45s}.drumroll .cinema-vignette{opacity:1}.stage-light{position:absolute;top:-35%;width:42%;height:145%;filter:blur(18px);mix-blend-mode:screen;opacity:0;transform-origin:50% 0;background:linear-gradient(180deg,rgba(255,239,181,.8),rgba(255,190,74,.16) 58%,transparent 82%)}.drumroll .stage-light{opacity:.75;animation:sweep 1.35s cubic-bezier(.45,0,.55,1) infinite alternate}.stage-light.left{left:-4%;transform:rotate(18deg)}.stage-light.right{right:-4%;transform:rotate(-18deg);animation-delay:-.68s}.drum-core{position:absolute;left:50%;top:50%;width:min(29vw,430px);aspect-ratio:1;border-radius:50%;transform:translate(-50%,-50%) scale(.25);opacity:0;border:clamp(3px,.4vw,8px) solid rgba(255,223,132,.9);box-shadow:0 0 35px #ffcf66,0 0 120px rgba(220,25,65,.9),inset 0 0 70px rgba(255,215,110,.45)}.drumroll .drum-core{animation:drumBeat .42s ease-in-out infinite alternate}.drum-line{position:absolute;left:50%;top:50%;width:8px;height:62vh;border-radius:99px;background:linear-gradient(#fff,rgba(255,200,76,.05));filter:drop-shadow(0 0 14px #ffd66f);transform-origin:50% 0;opacity:0}.drumroll .drum-line{animation:radialHit .84s ease-out infinite}.drum-line:nth-of-type(2){transform:rotate(60deg);animation-delay:-.14s}.drum-line:nth-of-type(3){transform:rotate(120deg);animation-delay:-.28s}.drum-line:nth-of-type(4){transform:rotate(180deg);animation-delay:-.42s}.drum-line:nth-of-type(5){transform:rotate(240deg);animation-delay:-.56s}.drum-line:nth-of-type(6){transform:rotate(300deg);animation-delay:-.7s}@keyframes sweep{to{transform:rotate(-22deg);opacity:.35}}@keyframes drumBeat{to{transform:translate(-50%,-50%) scale(1.08);opacity:.95;box-shadow:0 0 55px #fff1b8,0 0 170px rgba(223,22,66,.95),inset 0 0 90px rgba(255,225,145,.75)}}@keyframes radialHit{0%{opacity:0;scale:.15}28%{opacity:.85}100%{opacity:0;scale:1.7}}</style></head><body><iframe id="feed" title="BDC Live Display Feed" allow="fullscreen"></iframe><div id="fx" class="fx"><canvas id="fxCanvas"></canvas><div class="stage-light left"></div><div class="stage-light right"></div><div class="drum-core"></div><div class="drum-line"></div><div class="drum-line"></div><div class="drum-line"></div><div class="drum-line"></div><div class="drum-line"></div><div class="drum-line"></div><div class="cinema-vignette"></div></div><script>
const token=<?=json_encode($token)?>,feed=document.querySelector('#feed'),fx=document.querySelector('#fx'),canvas=document.querySelector('#fxCanvas'),ctx=canvas.getContext('2d');let fingerprint='',effectFingerprint='',timerFingerprint='',pageTimer=null,busy=false,fxFrame=0,fxTimer=0,particles=[],rockets=[];
const palette=['#ffffff','#ffd166','#ff3158','#ff7b00','#38bdf8','#a78bfa','#34d399'];
function sizeCanvas(){const d=Math.min(2,devicePixelRatio||1);canvas.width=Math.floor(innerWidth*d);canvas.height=Math.floor(innerHeight*d);canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';ctx.setTransform(d,0,0,d,0,0)}
function stopEffect(){cancelAnimationFrame(fxFrame);clearTimeout(fxTimer);particles=[];rockets=[];ctx.clearRect(0,0,innerWidth,innerHeight);fx.className='fx'}
function burst(x,y,count=110){const color=palette[Math.floor(Math.random()*palette.length)];for(let i=0;i<count;i++){const a=Math.PI*2*i/count+(Math.random()-.5)*.08,s=(2.2+Math.random()*7.2)*(innerWidth/1920+.45);particles.push({kind:'spark',x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:1,decay:.008+Math.random()*.01,size:1+Math.random()*2.5,color,trail:[]})}}
function fireworks(){let last=0,launched=0;function frame(t){ctx.fillStyle='rgba(0,0,8,.18)';ctx.fillRect(0,0,innerWidth,innerHeight);if(t-last>330&&launched<15){last=t;launched++;rockets.push({x:innerWidth*(.1+Math.random()*.8),y:innerHeight+20,vx:(Math.random()-.5)*1.1,vy:-(9+Math.random()*5),target:innerHeight*(.12+Math.random()*.48),color:palette[Math.floor(Math.random()*palette.length)]})}rockets.forEach((r,i)=>{r.x+=r.vx;r.y+=r.vy;r.vy+=.035;ctx.beginPath();ctx.moveTo(r.x,r.y+34);ctx.lineTo(r.x,r.y);ctx.strokeStyle=r.color;ctx.lineWidth=3;ctx.shadowBlur=22;ctx.shadowColor=r.color;ctx.stroke();if(r.y<=r.target||r.vy>0){burst(r.x,r.y,95+Math.floor(Math.random()*65));rockets.splice(i,1)}});particles.forEach((p,i)=>{p.trail.unshift([p.x,p.y]);if(p.trail.length>7)p.trail.pop();p.x+=p.vx;p.y+=p.vy;p.vx*=.987;p.vy=p.vy*.987+.055;p.life-=p.decay;ctx.beginPath();p.trail.forEach((q,n)=>n?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]));ctx.strokeStyle=p.color;ctx.globalAlpha=Math.max(0,p.life);ctx.lineWidth=p.size;ctx.shadowBlur=18;ctx.shadowColor=p.color;ctx.stroke();if(p.life<=0)particles.splice(i,1)});ctx.globalAlpha=1;ctx.shadowBlur=0;fxFrame=requestAnimationFrame(frame)}fxFrame=requestAnimationFrame(frame);fxTimer=setTimeout(stopEffect,7200)}
function confetti(){const colors=['#f5c451','#ef233c','#ffffff','#2563eb','#14b8a6','#9333ea'];for(let i=0;i<320;i++)particles.push({x:Math.random()*innerWidth,y:-Math.random()*innerHeight*1.2,w:5+Math.random()*12,h:3+Math.random()*7,vx:(Math.random()-.5)*3,vy:2.2+Math.random()*5,rot:Math.random()*6.28,vr:(Math.random()-.5)*.24,color:colors[i%colors.length],wave:Math.random()*6.28});function frame(){ctx.clearRect(0,0,innerWidth,innerHeight);particles.forEach(p=>{p.wave+=.035;p.x+=p.vx+Math.sin(p.wave)*1.2;p.y+=p.vy;p.rot+=p.vr;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.fillStyle=p.color;ctx.shadowBlur=7;ctx.shadowColor='rgba(255,255,255,.32)';ctx.fillRect(-p.w/2,-p.h/2,p.w,p.h);ctx.restore()});particles=particles.filter(p=>p.y<innerHeight+35);if(particles.length)fxFrame=requestAnimationFrame(frame)}fxFrame=requestAnimationFrame(frame);fxTimer=setTimeout(stopEffect,8000)}
function drumroll(){ctx.clearRect(0,0,innerWidth,innerHeight);let start=performance.now();function frame(t){ctx.clearRect(0,0,innerWidth,innerHeight);const age=t-start,intensity=.28+.72*Math.min(1,age/4200),cx=innerWidth/2,cy=innerHeight/2;for(let i=0;i<9;i++){const r=((age*(.22+i*.015))%(Math.max(innerWidth,innerHeight)*.62));ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.strokeStyle=`rgba(255,210,105,${Math.max(0,(1-r/(Math.max(innerWidth,innerHeight)*.62))*.18*intensity)})`;ctx.lineWidth=2+i*.25;ctx.stroke()}fxFrame=requestAnimationFrame(frame)}fxFrame=requestAnimationFrame(frame);fxTimer=setTimeout(stopEffect,5600)}
function effect(s){const key=[s.effect_type,s.effect_version].join('|');if(key===effectFingerprint)return;effectFingerprint=key;stopEffect();if(!s.effect_type)return;sizeCanvas();fx.className='fx on '+s.effect_type;if(s.effect_type==='fireworks')fireworks();else if(s.effect_type==='confetti')confetti();else if(s.effect_type==='drumroll')drumroll()}
addEventListener('resize',sizeCanvas);
function load(s){effect(s);const fp=[s.state_version,s.data_version||0,s.screen_type,s.round_id,s.page_number,s.reveal_place].join('|');if(fp!==fingerprint){fingerprint=fp;const endpoint=s.screen_type==='winners'&&!s.reveal_place?'podium-ready.php':s.screen_type==='final_results'?'final-relative-placement.php':'feed.php';feed.src=endpoint+'?token='+encodeURIComponent(token)+'&v='+encodeURIComponent(fp)+'&_='+Date.now()}const tf=[s.auto_page,s.page_delay_seconds,s.total_pages,s.screen_type].join('|');if(tf===timerFingerprint)return;timerFingerprint=tf;clearInterval(pageTimer);if(!s.loop_enabled&&s.auto_page&&s.total_pages>1&&['competitors','callbacks','finalists'].includes(s.screen_type))pageTimer=setInterval(async()=>{try{await fetch('advance.php?token='+encodeURIComponent(token),{method:'POST',cache:'no-store'});await tick()}catch(e){}},Number(s.page_delay_seconds)*1000)}
async function tick(){if(busy)return;busy=true;try{const r=await fetch('state.php?token='+encodeURIComponent(token)+'&_='+Date.now(),{cache:'no-store'}),s=await r.json();if(s&&s.ok)load(s)}catch(e){}finally{busy=false}}tick();setInterval(tick,700);
